public class PaperTransformTestsV1 {
 static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=50000000};
 static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}
 static Polyline Rect(BlockTableRecord b,Transaction tr,double x,double width,bool closed){var p=new Polyline();p.AddVertexAt(0,new Point2d(x,2),0,0,0);p.AddVertexAt(1,new Point2d(x+width,2),0,0,0);if(closed){p.AddVertexAt(2,new Point2d(x+width,4),0,0,0);p.AddVertexAt(3,new Point2d(x,4),0,0,0);}p.Closed=closed;p.Elevation=63.2402787578;b.AppendEntity(p);tr.AddNewlyCreatedDBObject(p,true);return p;}
 static Hatch Fill(BlockTableRecord b,Transaction tr,Polyline p){var h=new Hatch();b.AppendEntity(h);tr.AddNewlyCreatedDBObject(h,true);h.SetHatchPattern(HatchPatternType.PreDefined,"SOLID");h.Elevation=p.Elevation;var c=new Curve2dCollection();var t=new IntegerCollection();try{for(int k=0;k<4;k++){c.Add(new LineSegment2d(p.GetPoint2dAt(k),p.GetPoint2dAt((k+1)%4)));t.Add(1);}h.AppendLoop(HatchLoopTypes.External,c,t);h.EvaluateHatch(true);}finally{foreach(Curve2d e in c)e.Dispose();}return h;}
 static PaperTransformOpsV1.Item Item(Entity e,double scale,double dx){return new PaperTransformOpsV1.Item{handle=e.Handle.ToString(),type=e.GetRXClass().Name,layer=e.Layer,before=J.DeserializeObject(J.Serialize(NativeGeometryReadV1.Geometry(e))),scale_x=scale,offset_x=dx,offset_y=7};}
 static string Protected(Database db,string[] handles){var rows=new List<object>();using(var tr=db.TransactionManager.StartTransaction())foreach(string handle in handles){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(handle,16)),0),OpenMode.ForRead);rows.Add(new{handle=e.Handle.ToString(),layer=e.Layer,owner=e.OwnerId.Handle.ToString(),geometry=NativeGeometryReadV1.Geometry(e)});}return J.Serialize(rows);}
 [CommandMethod("HLCADPAPERTRANSFORMTESTV3",CommandFlags.Session)]public void Run(){var a=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("\nFolder:"){AllowSpaces=true});string dir=a.StringResult.Trim('"'),receipt=Path.Combine(dir,"paper_transform_native.receipt.json"),output=Path.Combine(dir,"paper_transform_native.dwg");try{Need(!File.Exists(receipt)&&!File.Exists(output),"TEST_OUTPUT_EXISTS");string expected,protectedBefore,styles,layout;string[] protectedHandles;var items=new List<PaperTransformOpsV1.Item>();bool wrongGeometryRejected=false,wrongSpaceRejected=false;object changes;
 using(var db=new Database(true,true)){using(var tr=db.TransactionManager.StartTransaction()){var b=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockPaperSpaceId(db),OpenMode.ForWrite);layout=((Layout)tr.GetObject(b.LayoutId,OpenMode.ForRead)).LayoutName;double unit=50*0.33330098762982396;var first=Rect(b,tr,10,12.5,true);items.Add(Item(first,unit/12.5,10-10*unit/12.5));var second=Rect(b,tr,22.5,12.5,true);items.Add(Item(second,unit/12.5,10+unit-22.5*unit/12.5));items.Add(Item(Fill(b,tr,second),unit/12.5,10+unit-22.5*unit/12.5));var fourth=Rect(b,tr,47.5,10,true);items.Add(Item(fourth,unit/10,10+3*unit-47.5*unit/10));items.Add(Item(Fill(b,tr,fourth),unit/10,10+3*unit-47.5*unit/10));var frame=Rect(b,tr,10,40,true);items.Add(Item(frame,4*unit/40,10-10*4*unit/40));var divider=Rect(b,tr,35,0,false);items.Add(Item(divider,1,10+3*unit-35));var keep=Rect(b,tr,200,5,true);var model=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForWrite);var point=new Line(new Point3d(9,8,7),new Point3d(10,12,7));model.AppendEntity(point);tr.AddNewlyCreatedDBObject(point,true);protectedHandles=new[]{keep.Handle.ToString(),point.Handle.ToString()};var order=(DrawOrderTable)tr.GetObject(b.DrawOrderTableId,OpenMode.ForWrite);order.MoveToTop(new ObjectIdCollection(new[]{keep.ObjectId}));tr.Commit();}
 var job=new BoundCadEditsV6.Job{layout=layout,transforms=items.ToArray(),input=Path.Combine(dir,"paper_transform_source.dwg")};db.SaveAs(job.input,DwgVersion.AC1032);job.input_sha256=NativeGeometryReadV1.Hash(job.input);string original=PaperTransformOpsV1.Snapshot(db,job);protectedBefore=Protected(db,protectedHandles);styles=J.Serialize(NativeTextStylesV1.Snapshot(db));
 var old=items[6].before;items[6].before=new{wrong=true};try{PaperTransformOpsV1.Apply(db,job,()=>{throw new InvalidOperationException("MUTATED_BEFORE_ALL_PREFLIGHT");});}catch(InvalidOperationException e){wrongGeometryRejected=e.Message.StartsWith("PAPER_ORIGINAL_GEOMETRY_CHANGED");}items[6].before=old;Need(wrongGeometryRejected&&original==PaperTransformOpsV1.Snapshot(db,job),"FAILED_ATOMIC_PREFLIGHT");
 job.layout="Model";try{PaperTransformOpsV1.Apply(db,job,()=>{throw new InvalidOperationException("MODEL_MUTATION");});}catch(InvalidOperationException e){wrongSpaceRejected=e.Message=="UNIQUE_PAPER_TRANSFORMS_REQUIRED";}job.layout=layout;Need(wrongSpaceRejected,"MODEL_NOT_REJECTED");changes=PaperTransformOpsV1.Apply(db,job,()=>{var tr=db.TransactionManager.TopTransaction;var b=(BlockTableRecord)tr.GetObject(BoundCadEditsV6.Space(tr,db,layout),OpenMode.ForRead);var order=(DrawOrderTable)tr.GetObject(b.DrawOrderTableId,OpenMode.ForWrite);order.MoveToTop(new ObjectIdCollection(new[]{db.GetObjectId(false,new Handle(Convert.ToInt64(protectedHandles[0],16)),0)}));});Need(Convert.ToInt32(((Dictionary<string,object>)J.DeserializeObject(J.Serialize(changes)))["draw_order_notifications"])>0,"DRAW_ORDER_NOTICE_NOT_REPRODUCED");Need(protectedBefore==Protected(db,protectedHandles)&&styles==J.Serialize(NativeTextStylesV1.Snapshot(db)),"UNSELECTED_CHANGED");
 using(var tr=db.TransactionManager.StartTransaction()){foreach(int i in new[]{0,1,3}){var p=(Polyline)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(items[i].handle,16)),0),OpenMode.ForRead);Need(Math.Abs(p.GetPoint2dAt(1).X-p.GetPoint2dAt(0).X-16.665049381491198)<1e-9,"UNEQUAL_TEST_SEGMENTS");Need(p.Elevation==63.2402787578,"Z_CHANGED");}}
 expected=PaperTransformOpsV1.Snapshot(db,job);db.SaveAs(output,DwgVersion.AC1032);string sortHandle;using(var tr=db.TransactionManager.StartTransaction()){sortHandle=((BlockTableRecord)tr.GetObject(BoundCadEditsV6.Space(tr,db,layout),OpenMode.ForRead)).DrawOrderTableId.Handle.ToString();}PaperTransformRecoveryV1.VerifyEmergency(db,job,output,NativeGeometryReadV1.Hash(output),sortHandle);bool badSaved=false;try{PaperTransformRecoveryV1.VerifyEmergency(db,job,job.input,job.input_sha256,sortHandle);}catch(InvalidOperationException e){badSaved=e.Message=="EMERGENCY_NOT_EXACT_EXPECTED_RESULT";}Need(badSaved,"RECOVERY_ACCEPTED_UNTRANSFORMED_FILE");}
 using(var db=new Database(false,true)){db.ReadDwgFile(output,FileOpenMode.OpenForReadAndAllShare,true,"");db.CloseInput(true);Need(CadValueCompareV1.Json(expected,PaperTransformOpsV1.Snapshot(db,new BoundCadEditsV6.Job{layout=layout,transforms=items.ToArray()})),"SAVE_REOPEN_SELECTED_DIFFERENCE");Need(CadValueCompareV1.Json(protectedBefore,Protected(db,protectedHandles)),"SAVE_REOPEN_PROTECTED_DIFFERENCE");Need(styles==J.Serialize(NativeTextStylesV1.Snapshot(db)),"SAVE_REOPEN_STYLE_DIFFERENCE");}
 File.WriteAllText(receipt,J.Serialize(new{status="ISOLATED_NATIVE_PAPER_TRANSFORM_VERIFIED",output,layout,transforms=items,changes,saved_reopened=true,draw_order_notification_reproduced=true,emergency_recovery_verified=true,untransformed_emergency_rejected=true,wrong_geometry_rejected_without_mutation=wrongGeometryRejected,model_space_rejected=wrongSpaceRejected,protected_objects_and_styles_unchanged=true,scope="synthetic straight paper polylines and non-associative SOLID LINE loops; per-object X scale and XY offset; high elevation preserved"}));
 }catch(System.Exception e){File.WriteAllText(receipt,J.Serialize(new{status="ISOLATED_TEST_FAILED",error=e.ToString()}));}}
